        BufferedReader input = new BufferedReader(new InputStreamReader(System.in));
        int size = Integer.parseInt(input.readLine());
        int maxSequenceLength = 0, totalWordsCount = 0, outsideCounter = 0, insideCounter = 0;
        boolean inParentheses = false;
        String lineInput = input.readLine();
        char[] charsArray = lineInput.toCharArray();

        for (int i = 0; i < size; i++) {
            char ch = charsArray[i];
            if (ch == '(') {
                inParentheses = true;
                outsideCounter = 0;
            } else if (ch == ')') {
                inParentheses = false;
                if (insideCounter > 0) {
                    totalWordsCount++;
                    insideCounter = 0;
                }
            } else {
                if (inParentheses) {
                    if (ch != '_') {
                        insideCounter++;
                    } else {
                        if (insideCounter > 0) {
                            totalWordsCount++;
                            insideCounter = 0;
                        }
                    }
                } else {
                    if (ch != '_') {
                        outsideCounter++;
                    } else {
                        outsideCounter = 0;
                    }
                }
            }
            if (outsideCounter >= maxSequenceLength) {
                maxSequenceLength = outsideCounter;
            }
        }
        System.out.println(maxSequenceLength);
        System.out.println(totalWordsCount);
    }
}
